describe("rule NoteIdea", () => {
  it("creates the idea with who noted it, when, and its clock started at that moment", () => {
    const idea = must(
      noteIdea(
        {
          id: recipeIdeaId("i1"),
          member: ME,
          title: "etwas mit Kürbis",
          note: "Hokkaido aus dem Garten",
          inspirationLink: "https://example.org/insta",
        },
        T0,
      ),
    );
    expect(idea).toEqual({
      id: recipeIdeaId("i1"),
      title: "etwas mit Kürbis",
      note: "Hokkaido aus dem Garten",
      inspirationLink: "https://example.org/insta",
      addedBy: ME,
      addedAt: T0,
      lastTouchedAt: T0,
      archivedAt: null,
      candidates: [],
    });
  });

  it("takes note and inspiration link as optional: absent means null", () => {
    const idea = must(noteIdea({ id: recipeIdeaId("i1"), member: AC, title: "Kürbisgnocchi" }, T0));
    expect(idea.note).toBeNull();
    expect(idea.inspirationLink).toBeNull();
    expect(idea.addedBy).toBe(AC);
  });

  it("is rejected without a title", () => {
    expect(noteIdea({ id: recipeIdeaId("i1"), member: ME, title: "" }, T0)).toEqual({
      ok: false,
      reason: "empty_title",
    });
    expect(noteIdea({ id: recipeIdeaId("i1"), member: ME, title: "   " }, T0)).toEqual({
      ok: false,
      reason: "empty_title",
    });
  });
});

describe("rule EditIdea", () => {
  it("changes title, note and link, keeps who noted it and when, keeps its candidates, and moves the clock", () => {
    const idea = anIdea({ note: "alt", inspirationLink: "https://example.org/alt", candidates: [proposal(1)] });
    const later = T0 + 3 * WEEK;
    const edited = must(
      editIdea(
        idea,
        { member: AC, title: "Kürbisgnocchi mit Salbei", note: "neu", inspirationLink: "https://x.org" },
        later,
      ),
    );
    expect(edited).toEqual({
      ...idea,
      title: "Kürbisgnocchi mit Salbei",
      note: "neu",
      inspirationLink: "https://x.org",
      lastTouchedAt: later,
    });
    expect(edited.addedBy).toBe(ME);
    expect(edited.addedAt).toBe(T0);
    expect(edited.candidates).toEqual([proposal(1)]);
  });

  it("clears a note and link that are no longer given", () => {
    const idea = anIdea({ note: "alt", inspirationLink: "https://example.org/alt" });
    const edited = must(editIdea(idea, { member: ME, title: "Kürbisgnocchi" }, T0 + MINUTE));
    expect(edited.note).toBeNull();
    expect(edited.inspirationLink).toBeNull();
  });

  it("is rejected without a title, and the idea stays as it was", () => {
    const idea = anIdea();
    expect(editIdea(idea, { member: ME, title: "" }, T0 + MINUTE)).toEqual({ ok: false, reason: "empty_title" });
    expect(editIdea(idea, { member: ME, title: "  " }, T0 + MINUTE)).toEqual({ ok: false, reason: "empty_title" });
  });
});

describe("derived is_stale", () => {
  const config = defaultIdeaConfig;

  it("is false while the idea was touched within the stale period", () => {
    expect(isStale(anIdea(), T0, config)).toBe(false);
    expect(isStale(anIdea(), T0 + 8 * WEEK - 1, config)).toBe(false);
  });

  it("is true exactly when the stale period has passed since the last touch, and after", () => {
    expect(isStale(anIdea(), T0 + 8 * WEEK, config)).toBe(true);
    expect(isStale(anIdea(), T0 + 20 * WEEK, config)).toBe(true);
  });

  it("counts from the last touch, not from when the idea was added", () => {
    const touched = anIdea({ lastTouchedAt: T0 + 4 * WEEK });
    expect(isStale(touched, T0 + 8 * WEEK, config)).toBe(false);
    expect(isStale(touched, T0 + 12 * WEEK, config)).toBe(true);
  });

  it("follows the configured period", () => {
    const short: IdeaConfig = { ...config, ideaStaleAfterMs: HOUR };
    expect(isStale(anIdea(), T0 + HOUR - 1, short)).toBe(false);
    expect(isStale(anIdea(), T0 + HOUR, short)).toBe(true);
  });
});

describe("rule KeepIdea", () => {
  const config = defaultIdeaConfig;

  it("starts the clock of a stale idea again, so it is no longer stale", () => {
    const now = T0 + 9 * WEEK;
    const kept = must(keepIdea(anIdea({ candidates: [proposal(1)] }), { member: AC }, now, config));
    expect(kept.lastTouchedAt).toBe(now);
    expect(kept.addedAt).toBe(T0);
    expect(kept.candidates).toEqual([proposal(1)]);
    expect(isStale(kept, now, config)).toBe(false);
  });

  it("is rejected for an idea that is not stale", () => {
    expect(keepIdea(anIdea(), { member: ME }, T0 + WEEK, config)).toEqual({ ok: false, reason: "not_stale" });
  });
});

describe("the research model's answer (CandidateProposal)", () => {
  const config = defaultIdeaConfig;

  it("becomes candidate proposals with title, link and summary", () => {
    const found = reviewCandidates(
      { candidates: [{ title: "Kürbisgnocchi", link: "https://example.org/gnocchi", summary: "Mit Salbeibutter" }] },
      config,
    );
    expect(found).toEqual([
      { title: "Kürbisgnocchi", link: "https://example.org/gnocchi", summary: "Mit Salbeibutter" },
    ]);
  });

  it("compares proposals by value", () => {
    const answer = { candidates: [{ title: "A", link: "https://example.org/a", summary: "s" }] };
    expect(reviewCandidates(answer, config)).toEqual(reviewCandidates(structuredClone(answer), config));
  });

  it("drops a candidate whose link is not an http(s) web link", () => {
    const found = reviewCandidates(
      {
        candidates: [
          { title: "ok", link: "https://example.org/ok", summary: "" },
          { title: "plain http", link: "http://example.org/plain", summary: "" },
          { title: "script", link: "javascript:alert(1)", summary: "" },
          { title: "ftp", link: "ftp://example.org/r", summary: "" },
          { title: "relative", link: "/rezept", summary: "" },
          { title: "no link", link: "Kürbisgnocchi", summary: "" },
          { title: "missing link", summary: "" },
        ],
      },
      config,
    );
    expect(found.map((c) => c.title)).toEqual(["ok", "plain http"]);
  });

  it("carries no links or markup in its text", () => {
    const [c] = reviewCandidates(
      {
        candidates: [
          {
            title: "<b>Kürbisgnocchi</b>",
            link: "https://example.org/g",
            summary: "Siehe https://evil.example/x <script>x</script>lecker",
          },
        ],
      },
      config,
    );
    expect(c?.title).toBe("Kürbisgnocchi");
    expect(c?.summary).not.toMatch(/https?:|<|>/);
    expect(c?.summary).toContain("lecker");
  });

  it("keeps at most the configured number of candidates, dropping any beyond", () => {
    const many = { candidates: Array.from({ length: 8 }, (_, i) => proposal(i + 1)) };
    expect(reviewCandidates(many, config)).toEqual([1, 2, 3, 4, 5].map((n) => proposal(n)));
    expect(reviewCandidates(many, { ...config, maxCandidates: 2 })).toEqual([proposal(1), proposal(2)]);
  });

  it("gives nothing for an answer that does not fit the candidates' shape", () => {
    for (const answer of [null, "Here are some recipes!", 42, [], {}, { candidates: "x" }, { candidates: [1, null] }])
      expect(reviewCandidates(answer, config)).toEqual([]);
  });
});

describe("rule ReplaceCandidates", () => {
  const config = defaultIdeaConfig;
  const later = T0 + 2 * WEEK;

  it("replaces the earlier candidates with the new ones and moves the idea's clock", () => {
    const idea = anIdea({ candidates: [proposal(1), proposal(2)] });
    const replaced = must(replaceCandidates(idea, [proposal(3)], later, config));
    expect(replaced.candidates).toEqual([proposal(3)]);
    expect(replaced.lastTouchedAt).toBe(later);
    expect(replaced.title).toBe(idea.title);
    expect(replaced.addedAt).toBe(T0);
  });

  it("accepts exactly the maximum number of candidates", () => {
    const five = [1, 2, 3, 4, 5].map((n) => proposal(n));
    expect(must(replaceCandidates(anIdea(), five, later, config)).candidates).toEqual(five);
  });

  it("is rejected when no candidate was found, so the idea keeps its candidates and its clock", () => {
    expect(replaceCandidates(anIdea({ candidates: [proposal(1)] }), [], later, config)).toEqual({
      ok: false,
      reason: "no_candidates",
    });
  });

  it("is rejected when there are more candidates than the configured maximum", () => {
    const six = [1, 2, 3, 4, 5, 6].map((n) => proposal(n));
    const r = replaceCandidates(anIdea(), six, later, config);
    expect(r.ok).toBe(false);
  });
});

describe("rule PickCandidate", () => {
  it("hands the candidate's link to the import as its source and moves the idea's clock", () => {
    const idea = anIdea({ candidates: [proposal(1), proposal(2)] });
    const now = T0 + WEEK;
    const picked = must(pickCandidate(idea, { member: AC, candidate: 1 }, now));
    expect(picked.source).toBe("https://example.org/rezept-2");
    expect(picked.idea).toEqual({ ...idea, lastTouchedAt: now });
  });

  it("is rejected for a candidate the idea does not have", () => {
    const idea = anIdea({ candidates: [proposal(1)] });
    expect(pickCandidate(idea, { member: ME, candidate: 1 }, T0)).toEqual({ ok: false, reason: "no_such_candidate" });
    expect(pickCandidate(idea, { member: ME, candidate: -1 }, T0)).toEqual({ ok: false, reason: "no_such_candidate" });
  });
});

describe("rule UseOwnRecipe", () => {
  it("moves the idea's clock and leaves everything else as it was", () => {
    const idea = anIdea({ candidates: [proposal(1)] });
    const now = T0 + WEEK;
    expect(useOwnRecipe(idea, { member: AC }, now)).toEqual({ ...idea, lastTouchedAt: now });
  });
});

describe("rule ResearchIdea: the hourly limit per member", () => {
  const config = defaultIdeaConfig;
  const now = T0 + 5 * HOUR;
  const requests = (n: number, by = ME, at = now - 10 * MINUTE): ResearchRequest[] =>
    Array.from({ length: n }, () => ({ requestedBy: by, requestedAt: at }));

  it("allows a research while the member asked fewer than the limit within the last hour", () => {
    expect(mayResearch([], ME, now, config)).toBe(true);
    expect(mayResearch(requests(19), ME, now, config)).toBe(true);
  });

  it("refuses once the member reached the limit within the last hour", () => {
    expect(mayResearch(requests(20), ME, now, config)).toBe(false);
    expect(mayResearch(requests(2), ME, now, { ...config, maxResearchPerHour: 2 })).toBe(false);
  });

  it("counts only the member's own requests", () => {
    expect(mayResearch(requests(20, AC), ME, now, config)).toBe(true);
    expect(mayResearch(requests(20, AC), AC, now, config)).toBe(false);
  });

  it("forgets a request once an hour has passed since it", () => {
    expect(mayResearch(requests(20, ME, now - HOUR), ME, now, config)).toBe(true);
    expect(mayResearch(requests(20, ME, now - HOUR + 1), ME, now, config)).toBe(false);
  });
});
